public int MaxProfit(int[] prices) {
    int minPrice = int.MaxValue, best = 0;
    foreach (int p in prices) {
        minPrice = Math.Min(minPrice, p);       // best buy up to and including today
        best = Math.Max(best, p - minPrice);    // sell today
    }
    return best;
}

