public bool CanJump(int[] nums) {
    int reach = 0;                               // the farthest reachable cell
    for (int i = 0; i < nums.Length; i++) {
        if (i > reach) return false;             // i is unreachable, and so is everything beyond
        reach = Math.Max(reach, i + nums[i]);
    }
    return true;
}

