public int MaxSubArray(int[] nums) {
    int cur = nums[0], best = nums[0];             // non-empty: start from the first, not 0
    for (int i = 1; i < nums.Length; i++) {
        cur = Math.Max(nums[i], cur + nums[i]);    // start over or extend
        best = Math.Max(best, cur);
    }
    return best;
}
