public int Jump(int[] nums) {                    // reaching the end is guaranteed
    int jumps = 0, curEnd = 0, farthest = 0;
    for (int i = 0; i < nums.Length - 1; i++) {
        farthest = Math.Max(farthest, i + nums[i]);
        if (i == curEnd) {                       // cells with this jump count are used up
            jumps++;
            curEnd = farthest;                   // the next layer: as far as we reached
        }
    }
    return jumps;
}
// [2, 3, 1, 1, 4]: i = 0 → 1 jump, boundary 2; i = 2 → 2 jumps, boundary 4 — answer 2
